<!doctype html><html lang="<?=e(locale())?>" data-theme="<?=e($u['theme'] ?? 'light')?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · BugTrack</title><link rel="stylesheet" href="<?=e(url('assets/style.css'))?>"><script defer src="<?=e(url('assets/app.js'))?>"></script></head><body>
<?php if($u): ?><aside class="sidebar"><a class="brand" href="<?=e(url('?page=dashboard'))?>"><span class="brand-mark">B</span> BugTrack</a><nav><a class="<?=($_GET['page']??'dashboard')==='dashboard'?'active':''?>" href="<?=e(url('?page=dashboard'))?>">◫ <?=e(t('dashboard'))?></a><a class="<?=($_GET['page']??'')==='projects'?'active':''?>" href="<?=e(url('?page=projects'))?>">▦ <?=e(t('projects'))?></a><a class="<?=($_GET['page']??'')==='issues'?'active':''?>" href="<?=e(url('?page=issues'))?>">☷ <?=e(t('issues'))?></a><a class="<?=($_GET['page']??'')==='notifications'?'active':''?>" href="<?=e(url('?page=notifications'))?>">◉ <?=e(t('notifications'))?> <?php if($unread):?><b class="count"><?=$unread?></b><?php endif;?></a></nav><div class="sidebar-bottom"><a href="<?=e(url('?page=profile'))?>" class="user-chip"><span class="avatar"><?=e(mb_strtoupper(mb_substr($u['name'],0,1)))?></span><span><?=e($u['name'])?><small><?=e(ucfirst($u['role']))?></small></span></a><form method="post" action="<?=e(url())?>"><?=csrf_input()?><input type="hidden" name="action" value="logout"><button class="sidebar-logout" type="submit"><?=e(t('logout'))?> ↗</button></form></div></aside><div class="main-wrap"><header class="topbar"><button class="menu-toggle" type="button" aria-label="Menu">☰</button><span><?=e($title)?></span><div class="top-actions"><form class="theme-form" method="post" action="<?=e(url())?>"><?=csrf_input()?><input type="hidden" name="action" value="theme_toggle"><input type="hidden" name="back" value="<?=e($_SERVER['QUERY_STRING'] ? '?'.$_SERVER['QUERY_STRING'] : '?page=dashboard')?>"><button class="theme-toggle" type="submit" aria-label="<?=e(t('theme_toggle'))?>" title="<?=e(t('theme_toggle'))?>"><?=$u['theme']==='dark'?'☀':'☾'?></button></form><a href="<?=e(url('?page=profile'))?>"><?=e(strtoupper(locale()))?></a><a href="<?=e(url('?page=notifications'))?>">◉<?php if($unread):?> <b><?=$unread?></b><?php endif;?></a></div></header><main class="content">
<?php else: ?><main class="auth-main"><?php endif; ?>
<?php if($flash):?><div class="flash <?=e($flash[1])?>"><?=e($flash[0])?></div><?php endif; ?>
<?php }
function layout_end(): void { echo '</main>'; if(user()) echo '</div>'; echo '</body></html>'; }
function pill(string $value, string $kind='status'): string { return '<span class="pill '.e($kind.'-'.$value).'">'.e(t($value)).'</span>'; }
function due_badge(array $i): string { if (empty($i['due_date']) || $i['status']==='done') return ''; $days=(int)((strtotime($i['due_date'])-strtotime(date('Y-m-d')))/86400); if ($days<0) return '<span class="due-badge overdue">'.e(t('overdue')).'</span>'; if ($days<=3) return '<span class="due-badge soon">'.e(t('due_soon')).'</span>'; return ''; }
function issue_card(array $i): void { ?><a class="issue-card" href="<?=e(url('?page=issue&id='.$i['id']))?>"><div class="card-top"><span class="mono muted"><?=e($i['project_key'].'-'.$i['number'])?></span><?=pill($i['type'],'type')?></div><strong><?=e($i['title'])?></strong><div class="card-bottom"><?=pill($i['priority'],'priority')?><?=due_badge($i)?><span class="muted assignee-name"><?=e($i['assignee_name'] ?: '—')?></span></div></a><?php }
function issue_form(?array $i, int $pid): void { $members=project_users($pid); $labels=all('SELECT * FROM labels WHERE project_id=? ORDER BY name',[$pid]); $selected=$i ? array_map('intval',q('SELECT label_id FROM issue_labels WHERE issue_id=?',[$i['id']])->fetchAll(PDO::FETCH_COLUMN)) : []; ?>
<form method="post" action="<?=e(url())?>" class="form-grid"><?=csrf_input()?><input type="hidden" name="action" value="<?=$i?'issue_update':'issue_create'?>"><input type="hidden" name="project_id" value="<?=$pid?>"><?php if($i):?><input type="hidden" name="issue_id" value="<?=$i['id']?>"><?php endif;?>
<label class="wide"><?=e(t('title'))?><input name="title" maxlength="200" required minlength="3" value="<?=e($i['title']??'')?>"></label><label class="wide"><?=e(t('description'))?><textarea name="description" rows="6"><?=e($i['description']??'')?></textarea></label>
<label><?=e(t('type'))?><select name="type"><?php foreach(['bug','task','feature'] as $v):?><option value="<?=$v?>" <?=($i['type']??'task')===$v?'selected':''?>><?=e(t($v))?></option><?php endforeach;?></select></label>
<label><?=e(t('status'))?><select name="status"><?php foreach(['backlog','todo','progress','review','done'] as $v):?><option value="<?=$v?>" <?=($i['status']??'backlog')===$v?'selected':''?>><?=e(t($v))?></option><?php endforeach;?></select></label>
<label><?=e(t('priority'))?><select name="priority"><?php foreach(['low','medium','high','critical'] as $v):?><option value="<?=$v?>" <?=($i['priority']??'medium')===$v?'selected':''?>><?=e(t($v))?></option><?php endforeach;?></select></label>
<label><?=e(t('assignee'))?><select name="assignee_id"><option value="0">—</option><?php foreach($members as $m):?><option value="<?=$m['id']?>" <?=(int)($i['assignee_id']??0)===(int)$m['id']?'selected':''?>><?=e($m['name'])?></option><?php endforeach;?></select></label>
<label><?=e(t('due_date'))?><input type="date" name="due_date" value="<?=e($i['due_date']??'')?>"></label><fieldset class="wide"><legend><?=e(t('labels'))?></legend><div class="checkbox-row"><?php foreach($labels as $l):?><label><input type="checkbox" name="labels[]" value="<?=$l['id']?>" <?=in_array((int)$l['id'],$selected,true)?'checked':''?>><span class="label-dot" style="background:<?=e($l['color'])?>"></span><?=e($l['name'])?></label><?php endforeach;?></div></fieldset>
<div class="wide form-actions"><button class="button primary" type="submit"><?=e(t('save'))?></button><a class="button subtle" href="<?=e(url($i?'?page=issue&id='.$i['id']:'?page=project&id='.$pid))?>"><?=e(t('cancel'))?></a></div></form><?php }

if ($page==='login' || $page==='register') {
    if(user()) redirect('?page=dashboard'); layout_start(t($page)); ?><div class="auth-card"><div class="brand"><span class="brand-mark">B</span> BugTrack</div><h1><?=e(t($page==='login'?'login_intro':'register_intro'))?></h1><p class="muted"><?=e(t('welcome'))?></p><form method="post" action="<?=e(url())?>" class="stack"><?=csrf_input()?><input type="hidden" name="action" value="<?=$page?>"><?php if($page==='register'):?><label><?=e(t('name'))?><input name="name" required minlength="2" maxlength="100"></label><?php endif;?><label><?=e(t('email'))?><input type="email" name="email" required></label><label><?=e(t('password'))?><input type="password" name="password" required <?= $page==='register'?'minlength="10"':'' ?>></label><button class="button primary" type="submit"><?=e(t($page))?></button></form><p class="auth-switch"><a href="<?=e(url('?page='.($page==='login'?'register':'login')))?>"><?=e(t($page==='login'?'register':'login'))?></a></p></div><?php layout_end(); return;
}
if ($page==='dashboard') {
    $u=login_required(); $visibility=role_admin() ? '1=1' : 'EXISTS(SELECT 1 FROM project_members pm WHERE pm.project_id=p.id AND pm.user_id='.(int)$u['id'].')';
    $stats=one("SELECT COUNT(DISTINCT p.id) projects,COUNT(i.id) total,SUM(i.status='done') completed,SUM(i.status<>'done') open_issues,SUM(i.assignee_id=".(int)$u['id']." AND i.status<>'done') my_issues FROM projects p LEFT JOIN issues i ON i.project_id=p.id WHERE $visibility");
    $recent=all("SELECT a.*,u.name user_name,p.name project_name FROM activity a JOIN users u ON u.id=a.user_id JOIN projects p ON p.id=a.project_id WHERE $visibility ORDER BY a.created_at DESC,a.id DESC LIMIT 10");
    $mine=all("SELECT i.*,p.`key` project_key,u.name assignee_name FROM issues i JOIN projects p ON p.id=i.project_id LEFT JOIN users u ON u.id=i.assignee_id WHERE i.assignee_id=? AND i.status<>'done' ORDER BY i.updated_at DESC LIMIT 6",[$u['id']]);
    layout_start(t('dashboard')); ?><div class="page-heading"><div><p class="eyebrow">WORKSPACE / OVERVIEW</p><h1><?=e(t('dashboard'))?></h1><p class="muted"><?=e(t('welcome'))?></p></div><?php if($u['role']!=='member'):?><a class="button primary" href="<?=e(url('?page=project_new'))?>">+ <?=e(t('new_project'))?></a><?php endif;?></div><div class="stats"><div><span><?=e(t('projects'))?></span><strong><?=(int)$stats['projects']?></strong></div><div><span><?=e(t('open_issues'))?></span><strong><?=(int)$stats['open_issues']?></strong></div><div><span><?=e(t('my_issues'))?></span><strong><?=(int)$stats['my_issues']?></strong></div><div><span><?=e(t('completed'))?></span><strong><?=(int)$stats['completed']?></strong></div></div><div class="two-col"><section class="panel"><div class="panel-head"><h2><?=e(t('my_issues'))?></h2><a href="<?=e(url('?page=issues&assignee=me'))?>"><?=e(t('all'))?> →</a></div><?php if(!$mine):?><p class="empty"><?=e(t('no_results'))?></p><?php else: foreach($mine as $i) issue_card($i); endif;?></section><section class="panel"><div class="panel-head"><h2><?=e(t('recent_activity'))?></h2></div><?php if(!$recent):?><p class="empty"><?=e(t('no_results'))?></p><?php else: foreach($recent as $a):?><div class="activity-row"><span class="avatar small"><?=e(mb_strtoupper(mb_substr($a['user_name'],0,1)))?></span><div><strong><?=e($a['user_name'])?></strong> <?=e(t($a['action']))?> <span class="muted"><?=e($a['detail'])?></span><small><?=e($a['project_name'])?> · <?=e($a['created_at'])?></small></div></div><?php endforeach; endif;?></section></div><?php layout_end(); return;
}
if ($page==='projects') {
    $u=login_required(); $search=trim((string)($_GET['q']??'')); $args=[]; $where=role_admin()?'1=1':'EXISTS(SELECT 1 FROM project_members pm WHERE pm.project_id=p.id AND pm.user_id='.(int)$u['id'].')';
    if($search!==''){ $where.=' AND (p.name LIKE ? OR p.`key` LIKE ?)'; $args=['%'.$search.'%','%'.$search.'%']; }
    $projects=all("SELECT p.*,u.name owner_name,(SELECT COUNT(*) FROM issues i WHERE i.project_id=p.id AND i.status<>'done') open_count,(SELECT COUNT(*) FROM project_members pm WHERE pm.project_id=p.id) member_count FROM projects p JOIN users u ON u.id=p.owner_id WHERE $where ORDER BY p.created_at DESC",$args);
    layout_start(t('projects')); ?><div class="page-heading"><div><p class="eyebrow">WORKSPACE / PROJECTS</p><h1><?=e(t('projects'))?></h1></div><?php if($u['role']!=='member'):?><a class="button primary" href="<?=e(url('?page=project_new'))?>">+ <?=e(t('new_project'))?></a><?php endif;?></div><form class="toolbar" method="get"><input type="hidden" name="page" value="projects"><input name="q" value="<?=e($search)?>" placeholder="<?=e(t('search'))?>"><button class="button" type="submit"><?=e(t('search'))?></button></form><div class="project-grid"><?php foreach($projects as $p):?><a class="project-tile" href="<?=e(url('?page=project&id='.$p['id']))?>"><div class="project-icon"><?=e(mb_substr($p['key'],0,2))?></div><div><span class="mono muted"><?=e($p['key'])?></span><h2><?=e($p['name'])?></h2><p><?=e(mb_strimwidth($p['description']??'',0,140,'…'))?></p><small><?=e($p['owner_name'])?> · <?=$p['member_count']?> <?=e(t('members'))?> · <?=$p['open_count']?> <?=e(t('open_issues'))?></small></div></a><?php endforeach;?></div><?php if(!$projects):?><p class="empty"><?=e(t('no_results'))?></p><?php endif; layout_end(); return;
}
if ($page==='project_new') {
    if(user()['role']==='member') abort(403,'Manager access required.'); layout_start(t('new_project')); ?><div class="page-heading"><div><p class="eyebrow">PROJECTS / NEW</p><h1><?=e(t('new_project'))?></h1></div></div><section class="panel narrow"><form method="post" action="<?=e(url())?>" class="stack"><?=csrf_input()?><input type="hidden" name="action" value="project_create"><label><?=e(t('project_name'))?><input name="name" required minlength="3" maxlength="120"></label><label><?=e(t('project_key'))?><input name="key" required minlength="2" maxlength="12" pattern="[A-Za-z][A-Za-z0-9]+" style="text-transform:uppercase"></label><label><?=e(t('description'))?><textarea name="description" rows="5"></textarea></label><button class="button primary" type="submit"><?=e(t('create'))?></button></form></section><?php layout_end(); return;
}
if ($page==='project' || $page==='board') {
    $p=require_project(positive_id($_GET['id']??0)); $pid=(int)$p['id']; $manage=can_manage($p);
    $members=project_users($pid); $labels=all('SELECT * FROM labels WHERE project_id=? ORDER BY name',[$pid]);
    $counts=all('SELECT status,COUNT(*) n FROM issues WHERE project_id=? GROUP BY status',[$pid]); $statusCounts=array_column($counts,'n','status');
    $issues=all('SELECT i.*,p.`key` project_key,u.name assignee_name FROM issues i JOIN projects p ON p.id=i.project_id LEFT JOIN users u ON u.id=i.assignee_id WHERE i.project_id=? ORDER BY i.updated_at DESC',[$pid]);
    layout_start($p['name']); ?><div class="page-heading"><div><p class="eyebrow"><a href="<?=e(url('?page=projects'))?>"><?=e(t('projects'))?></a> / <?=e($p['key'])?></p><h1><?=e($p['name'])?></h1><p class="muted"><?=e($p['description'])?></p></div><a class="button primary" href="<?=e(url('?page=issue_new&project_id='.$pid))?>">+ <?=e(t('new_issue'))?></a></div><div class="tabs"><a class="<?=$page==='project'?'active':''?>" href="<?=e(url('?page=project&id='.$pid))?>"><?=e(t('project_details'))?></a><a class="<?=$page==='board'?'active':''?>" href="<?=e(url('?page=board&id='.$pid))?>"><?=e(t('board'))?></a><a href="<?=e(url('?page=issues&project='.$pid))?>"><?=e(t('issues'))?></a></div>
    <?php if($page==='board'):?><div class="board-toolbar"><label class="board-search"><span>⌕</span><input type="search" id="board-search" placeholder="<?=e(t('board_search'))?>" aria-label="<?=e(t('board_search'))?>"></label><span class="board-total"><?=count($issues)?> <?=e(t('issues'))?></span></div><div class="board" data-csrf="<?=e(csrf())?>" data-url="<?=e(url())?>" data-error="<?=e(t('update_failed'))?>" data-saved="<?=e(t('save'))?>"><?php foreach(['backlog','todo','progress','review','done'] as $status):?><section class="board-column" data-status="<?=$status?>"><div class="board-head"><h2><?=e(t($status))?></h2><span><?= (int)($statusCounts[$status]??0) ?></span></div><div class="board-cards"><?php foreach($issues as $i): if($i['status']!==$status) continue;?><div class="board-item" draggable="true" data-issue="<?=$i['id']?>" data-search="<?=e(mb_strtolower($i['project_key'].'-'.$i['number'].' '.$i['title'].' '.($i['assignee_name']??'')))?>"><?php issue_card($i);?><label class="board-status-label"><span><?=e(t('move_to'))?></span><select class="board-status" aria-label="<?=e(t('move_to'))?>"><?php foreach(['backlog','todo','progress','review','done'] as $choice):?><option value="<?=$choice?>" <?=$i['status']===$choice?'selected':''?>><?=e(t($choice))?></option><?php endforeach;?></select></label></div><?php endforeach;?></div></section><?php endforeach;?></div><p class="board-no-results" hidden><?=e(t('board_empty'))?></p><p class="muted hint"><?=e(t('board_hint'))?></p>
    <?php else: ?><div class="stats compact"><?php foreach(['backlog','todo','progress','review','done'] as $status):?><div><span><?=e(t($status))?></span><strong><?=(int)($statusCounts[$status]??0)?></strong></div><?php endforeach;?></div><div class="two-col project-columns"><section class="panel"><div class="panel-head"><h2><?=e(t('issues'))?></h2><a href="<?=e(url('?page=issues&project='.$pid))?>"><?=e(t('all'))?> →</a></div><?php foreach(array_slice($issues,0,8) as $i) issue_card($i); if(!$issues):?><p class="empty"><?=e(t('no_results'))?></p><?php endif;?></section><div class="stack-panels"><section class="panel"><div class="panel-head"><h2><?=e(t('members'))?></h2></div><?php foreach($members as $m):?><div class="member-row"><span class="avatar small"><?=e(mb_strtoupper(mb_substr($m['name'],0,1)))?></span><div><strong><?=e($m['name'])?></strong><small><?=e($m['email'])?> · <?=e($m['role'])?></small></div><?php if($manage && (int)$m['id'] !== (int)$p['owner_id']):?><form method="post" action="<?=e(url())?>" data-confirm="<?=e(t('confirm_delete'))?>"><?=csrf_input()?><input type="hidden" name="action" value="member_remove"><input type="hidden" name="project_id" value="<?=$pid?>"><input type="hidden" name="user_id" value="<?=$m['id']?>"><button class="icon-button" title="<?=e(t('remove'))?>">×</button></form><?php endif;?></div><?php endforeach;?><?php if($manage):?><form method="post" action="<?=e(url())?>" class="inline-form"><?=csrf_input()?><input type="hidden" name="action" value="member_add"><input type="hidden" name="project_id" value="<?=$pid?>"><input type="email" name="email" placeholder="Email" required><select name="role"><option value="member">Member</option><option value="manager">Manager</option></select><button class="button" type="submit">+ <?=e(t('add_member'))?></button></form><?php endif;?></section><section class="panel"><div class="panel-head"><h2><?=e(t('labels'))?></h2></div><div class="label-list"><?php foreach($labels as $l):?><span class="label-item"><span class="label-dot" style="background:<?=e($l['color'])?>"></span><?=e($l['name'])?><?php if($manage):?><form method="post" action="<?=e(url())?>" data-confirm="<?=e(t('confirm_delete'))?>"><?=csrf_input()?><input type="hidden" name="action" value="label_remove"><input type="hidden" name="project_id" value="<?=$pid?>"><input type="hidden" name="label_id" value="<?=$l['id']?>"><button title="<?=e(t('remove'))?>">×</button></form><?php endif;?></span><?php endforeach;?></div><?php if($manage):?><form method="post" action="<?=e(url())?>" class="inline-form"><?=csrf_input()?><input type="hidden" name="action" value="label_add"><input type="hidden" name="project_id" value="<?=$pid?>"><input name="name" maxlength="40" required placeholder="<?=e(t('add_label'))?>"><input type="color" name="color" value="#5070b8"><button class="button" type="submit">+</button></form><?php endif;?></section><?php if($manage):?><section class="panel"><div class="panel-head"><h2><?=e(t('settings'))?></h2></div><form method="post" action="<?=e(url())?>" class="stack"><?=csrf_input()?><input type="hidden" name="action" value="project_update"><input type="hidden" name="project_id" value="<?=$pid?>"><label><?=e(t('project_name'))?><input name="name" value="<?=e($p['name'])?>" required minlength="3"></label><label><?=e(t('description'))?><textarea name="description" rows="3"><?=e($p['description'])?></textarea></label><button class="button" type="submit"><?=e(t('save'))?></button></form><?php if(role_admin() || (int)$p['owner_id']===(int)user()['id']):?><form method="post" action="<?=e(url())?>" data-confirm="<?=e(t('confirm_delete'))?>"><?=csrf_input()?><input type="hidden" name="action" value="project_delete"><input type="hidden" name="project_id" value="<?=$pid?>"><button class="button danger" type="submit"><?=e(t('delete'))?></button></form><?php endif;?></section><?php endif;?></div></div><?php endif; layout_end(); return;
}
if ($page==='issue_new' || $page==='issue_edit') {
    $i=$page==='issue_edit'?issue(positive_id($_GET['id']??0)):null; $pid=$i?(int)$i['project_id']:positive_id($_GET['project_id']??0); $p=require_project($pid); if($i && !can_edit_issue($i)) abort(403,'Cannot edit this issue.');
    layout_start($i?t('edit'):t('new_issue'));?><div class="page-heading"><div><p class="eyebrow"><a href="<?=e(url('?page=project&id='.$pid))?>"><?=e($p['key'])?></a> / <?=e(t('issues'))?></p><h1><?=e($i?t('edit'):t('new_issue'))?></h1></div></div><section class="panel form-panel"><?php issue_form($i,$pid);?></section><?php layout_end(); return;
