if ($page==='issue') {
    $i=issue(positive_id($_GET['id']??0)); $assignee=$i['assignee_id']?one('SELECT name FROM users WHERE id=?',[$i['assignee_id']]):null; $reporter=one('SELECT name FROM users WHERE id=?',[$i['reporter_id']]);
    $labels=all('SELECT l.* FROM issue_labels il JOIN labels l ON l.id=il.label_id WHERE il.issue_id=?',[$i['id']]);
