    $projectFilter=positive_id($_GET['project']??0); if($projectFilter){ require_project($projectFilter); $where[]='p.id=?'; $params[]=$projectFilter; }
    $search=mb_substr(trim((string)($_GET['q']??'')),0,100); if($search!==''){ $where[]='(i.title LIKE ? OR i.description LIKE ? OR CONCAT(p.`key`,"-",i.number) LIKE ?)'; array_push($params,'%'.$search.'%','%'.$search.'%','%'.$search.'%'); }
    foreach(['status'=>['backlog','todo','progress','review','done'],'priority'=>['low','medium','high','critical'],'type'=>['bug','task','feature']] as $field=>$values){ $value=(string)($_GET[$field]??''); if(in_array($value,$values,true)){ $where[]='i.'.$field.'=?'; $params[]=$value; } }
