    $total=(int)one('SELECT COUNT(*) n'.$from.$whereSql,$params)['n']; $perPage=15; $pageNum=max(1,min(100000,positive_id($_GET['p']??1)?:1)); $pages=max(1,(int)ceil($total/$perPage)); $pageNum=min($pageNum,$pages); $offset=($pageNum-1)*$perPage;
    $sort=allowed((string)($_GET['sort']??'updated'),['updated','created','due','priority'],'updated');
