    $stmt=db()->prepare('SELECT i.*,p.`key` project_key,p.name project_name,a.name assignee_name'.$from.$whereSql.' ORDER BY '.$sortSql.' LIMIT ? OFFSET ?');
    foreach($params as $index=>$value) $stmt->bindValue($index+1,$value,is_int($value)?PDO::PARAM_INT:PDO::PARAM_STR);
    $stmt->bindValue(count($params)+1,$perPage,PDO::PARAM_INT); $stmt->bindValue(count($params)+2,$offset,PDO::PARAM_INT); $stmt->execute(); $issues=$stmt->fetchAll();
    $projectOptions=role_admin()?all('SELECT id,name FROM projects ORDER BY name'):all('SELECT p.id,p.name FROM projects p JOIN project_members pm ON pm.project_id=p.id WHERE pm.user_id=? ORDER BY p.name',[$u['id']]);
