    layout_start(t('issues'));?><div class="page-heading"><div><p class="eyebrow">WORKSPACE / ISSUES</p><h1><?=e(t('issues'))?></h1><p class="muted"><?=$total?> <?=e(t('issues'))?></p></div></div><form method="get" class="filter-bar"><input type="hidden" name="page" value="issues"><input name="q" value="<?=e($search)?>" placeholder="<?=e(t('search'))?>"><select name="project"><option value=""><?=e(t('all'))?> <?=e(t('projects'))?></option><?php foreach($projectOptions as $p):?><option value="<?=$p['id']?>" <?=$projectFilter===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select><?php foreach(['status'=>['backlog','todo','progress','review','done'],'priority'=>['low','medium','high','critical'],'type'=>['bug','task','feature']] as $field=>$values):?><select name="<?=$field?>"><option value=""><?=e(t($field))?>: <?=e(t('all'))?></option><?php foreach($values as $v):?><option value="<?=$v?>" <?=($_GET[$field]??'')===$v?'selected':''?>><?=e(t($v))?></option><?php endforeach;?></select><?php endforeach;?><select name="assignee"><option value=""><?=e(t('assignee'))?>: <?=e(t('all'))?></option><option value="me" <?=$assignee==='me'?'selected':''?>><?=e(t('my_issues'))?></option><?php foreach($assigneeOptions as $a):?><option value="<?=$a['id']?>" <?=$assignee===(string)$a['id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach;?></select><select name="sort"><?php foreach(['updated','created','due','priority'] as $s):?><option value="<?=$s?>" <?=$sort===$s?'selected':''?>><?=e(t($s==='due'?'due_date':$s))?></option><?php endforeach;?></select><button class="button primary" type="submit"><?=e(t('filters'))?></button><a class="button subtle" href="<?=e(url('?page=issues'))?>"><?=e(t('clear'))?></a></form><div class="panel table-panel"><div class="table-scroll"><table><thead><tr><th><?=e(t('issues'))?></th><th><?=e(t('project_name'))?></th><th><?=e(t('type'))?></th><th><?=e(t('status'))?></th><th><?=e(t('priority'))?></th><th><?=e(t('assignee'))?></th><th><?=e(t('updated'))?></th></tr></thead><tbody><?php foreach($issues as $i):?><tr><td><a href="<?=e(url('?page=issue&id='.$i['id']))?>"><small class="mono muted"><?=e($i['project_key'].'-'.$i['number'])?></small><strong><?=e($i['title'])?></strong></a></td><td><?=e($i['project_name'])?></td><td><?=pill($i['type'],'type')?></td><td><?=pill($i['status'])?></td><td><?=pill($i['priority'],'priority')?></td><td><?=e($i['assignee_name']??'—')?></td><td><?=e(substr($i['updated_at'],0,10))?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$issues):?><p class="empty"><?=e(t('no_results'))?></p><?php endif;?></div><div class="pagination"><span><?=e(t('page'))?> <?=$pageNum?> / <?=$pages?></span><?php if($pageNum>1): $query=$_GET; $query['p']=$pageNum-1;?><a class="button" href="<?=e(url('?'.http_build_query($query)))?>"><?=e(t('previous'))?></a><?php endif; if($pageNum<$pages): $query=$_GET; $query['p']=$pageNum+1;?><a class="button" href="<?=e(url('?'.http_build_query($query)))?>"><?=e(t('next'))?></a><?php endif;?></div><?php layout_end(); return;
